/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  CheckCircle2,
  Clock3,
  ExternalLink,
  Film,
  ListOrdered,
  PauseCircle,
  PlayCircle,
  RotateCcw,
  Trophy,
} from "lucide-react";
import { picturePuzzleItems } from "../data/theme4GameData";
import useTheme4ModeData from "../hooks/useTheme4ModeData";
import useKeyboardShortcuts from "../hooks/useKeyboardShortcuts";
import Confetti from "../components/animations/Confetti";
import {
  logGameTelemetry,
  resetModeSessionId,
  saveXp,
  shuffleArray,
} from "../utils/gameHelpers";

const MODE_ID = "picture-puzzle";

function toPositiveInt(value, fallback) {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function toEmbedUrl(videoUrl) {
  try {
    const url = new URL(videoUrl);
    if (url.hostname.includes("youtu.be")) {
      const id = url.pathname.replace(/\//g, "");
      return id ? `https://www.youtube.com/embed/${id}?rel=0` : "";
    }
    const videoId = url.searchParams.get("v");
    return videoId ? `https://www.youtube.com/embed/${videoId}?rel=0` : "";
  } catch {
    return "";
  }
}

function normalizeSequenceRounds(data) {
  const source = Array.isArray(data) ? data : [];
  return source
    .map((item, itemIndex) => {
      const baseId = String(item?.id || `picture-sequence-${itemIndex + 1}`);
      const frames = (Array.isArray(item?.frames) ? item.frames : [])
        .map((frame, frameIndex) => ({
          id: frame?._adminId || `${baseId}-frame-${frameIndex + 1}`,
          imageUrl: String(frame?.imageUrl || "").trim(),
          order: toPositiveInt(frame?.order, frameIndex + 1),
          caption: String(frame?.caption || "").trim(),
        }))
        .filter((frame) => frame.imageUrl)
        .sort((a, b) => a.order - b.order)
        .map((frame, frameIndex) => ({ ...frame, order: frameIndex + 1 }));
      const videoUrl = String(item?.videoUrl || "").trim();
      if (!videoUrl || frames.length < 2) return null;
      return {
        id: baseId,
        title: String(item?.title || `Lượt ${itemIndex + 1}`),
        instruction: String(
          item?.instruction ||
            "Xem video rồi sắp xếp các khung hình theo đúng diễn biến lịch sử."
        ),
        videoUrl,
        embedUrl: toEmbedUrl(videoUrl),
        timeLimitSeconds: toPositiveInt(
          item?.timeLimitSeconds,
          Math.max(75, frames.length * 12)
        ),
        xpReward: toPositiveInt(item?.xpReward, 20),
        frames,
      };
    })
    .filter(Boolean);
}

export default function PictureSequenceMode() {
  const navigate = useNavigate();
  const { data: remotePicturePuzzleItems, loading } = useTheme4ModeData(
    MODE_ID,
    picturePuzzleItems
  );
  const activeRounds = useMemo(() => {
    const remoteRounds = normalizeSequenceRounds(remotePicturePuzzleItems);
    return remoteRounds.length > 0
      ? remoteRounds
      : normalizeSequenceRounds(picturePuzzleItems);
  }, [remotePicturePuzzleItems]);

  const [roundIndex, setRoundIndex] = useState(0);
  const [shuffledFrames, setShuffledFrames] = useState([]);
  const [selectedFrameIds, setSelectedFrameIds] = useState([]);
  const [feedback, setFeedback] = useState(null);
  const [incorrectSlots, setIncorrectSlots] = useState([]);
  const [finished, setFinished] = useState(false);
  const [score, setScore] = useState(0);
  const [correctCount, setCorrectCount] = useState(0);
  const [xpSaved, setXpSaved] = useState(false);
  const [sessionReady, setSessionReady] = useState(false);
  const [timeLeft, setTimeLeft] = useState(0);
  const [roundStarted, setRoundStarted] = useState(false);
  const [timerRunning, setTimerRunning] = useState(false);
  const [roundSolved, setRoundSolved] = useState(false);
  const startedAtRef = useRef(Date.now());

  const totalRounds = activeRounds.length;
  const currentRound = activeRounds[roundIndex] || null;
  const frameMap = useMemo(
    () => new Map((currentRound?.frames || []).map((frame) => [frame.id, frame])),
    [currentRound]
  );
  const selectedFrames = useMemo(
    () => selectedFrameIds.map((frameId) => frameMap.get(frameId)).filter(Boolean),
    [frameMap, selectedFrameIds]
  );
  const availableFrames = useMemo(() => {
    const selectedSet = new Set(selectedFrameIds);
    return shuffledFrames.filter((frame) => !selectedSet.has(frame.id));
  }, [selectedFrameIds, shuffledFrames]);

  const prepareRound = useCallback((nextRoundIndex, nextRounds = activeRounds) => {
    const nextRound = nextRounds[nextRoundIndex];
    if (!nextRound) return;
    setRoundIndex(nextRoundIndex);
    setShuffledFrames(shuffleArray(nextRound.frames));
    setSelectedFrameIds([]);
    setFeedback(null);
    setIncorrectSlots([]);
    setFinished(false);
    setTimeLeft(nextRound.timeLimitSeconds);
    setRoundStarted(false);
    setTimerRunning(false);
    setRoundSolved(false);
    setSessionReady(true);
  }, [activeRounds]);

  const resetSession = useCallback((replay = false) => {
    if (activeRounds.length === 0) return;
    resetModeSessionId(MODE_ID);
    startedAtRef.current = Date.now();
    logGameTelemetry(MODE_ID, "session_start", {
      totalRounds: activeRounds.length,
      replay,
    });
    setScore(0);
    setCorrectCount(0);
    setXpSaved(false);
    prepareRound(0, activeRounds);
  }, [activeRounds, prepareRound]);

  useEffect(() => {
    if (loading || totalRounds === 0) return;
    resetSession(false);
  }, [loading, resetSession, totalRounds]);

  useEffect(() => {
    if (!roundStarted || !timerRunning || finished || timeLeft <= 0) return undefined;
    const timer = window.setTimeout(() => setTimeLeft((prev) => prev - 1), 1000);
    return () => window.clearTimeout(timer);
  }, [finished, roundStarted, timeLeft, timerRunning]);

  useEffect(() => {
    if (finished && !xpSaved) {
      logGameTelemetry(MODE_ID, "session_end", {
        solved: true,
        score,
        correctCount,
        totalRounds,
        durationMs: Date.now() - startedAtRef.current,
      });
      saveXp(score);
      setXpSaved(true);
    }
  }, [correctCount, finished, score, totalRounds, xpSaved]);

  const checkArrangement = useCallback((timeUp = false) => {
    if (!currentRound) return;
    setRoundStarted(false);
    setTimerRunning(false);
    const correctIds = currentRound.frames.map((frame) => frame.id);
    const wrongPositions = correctIds.reduce((indexes, frameId, index) => {
      if (selectedFrameIds[index] !== frameId) indexes.push(index);
      return indexes;
    }, []);
    if (wrongPositions.length > 0) {
      const missingCount = Math.max(correctIds.length - selectedFrameIds.length, 0);
      setIncorrectSlots(wrongPositions);
      setFeedback({
        type: timeUp ? "error" : "warning",
        text: timeUp
          ? `Hết thời gian. Còn ${wrongPositions.length} vị trí chưa khớp${missingCount > 0 ? ` và thiếu ${missingCount} khung hình.` : "."}`
          : `Chưa đúng. Có ${wrongPositions.length} vị trí đang sai thứ tự${missingCount > 0 ? ` và thiếu ${missingCount} khung hình.` : "."}`,
      });
      logGameTelemetry(MODE_ID, "answer_submitted", {
        correct: false,
        roundIndex: roundIndex + 1,
        reason: timeUp ? "time_up_wrong_order" : "wrong_order",
        wrongPositions: wrongPositions.length,
        missingCount,
        title: currentRound.title,
      });
      return;
    }
    const nextScore = score + currentRound.xpReward;
    setIncorrectSlots([]);
    setFeedback({
      type: "success",
      text:
        roundIndex === totalRounds - 1
          ? `Bạn đã hoàn thành đúng cả ${totalRounds} video của Xâu chuỗi diễn biến.`
          : `Đúng rồi. Bạn đã xếp chuẩn ${currentRound.frames.length} khung hình của lượt ${roundIndex + 1}/${totalRounds}.`,
    });
    setScore(nextScore);
    setCorrectCount((prev) => prev + 1);
    setRoundSolved(true);
    logGameTelemetry(MODE_ID, "answer_submitted", {
      correct: true,
      roundIndex: roundIndex + 1,
      reason: timeUp ? "time_up_full_correct" : "full_correct",
      title: currentRound.title,
      scoreAfter: nextScore,
    });
    if (roundIndex === totalRounds - 1) setFinished(true);
  }, [currentRound, roundIndex, score, selectedFrameIds, totalRounds]);

  useEffect(() => {
    if (!roundStarted || !timerRunning || finished || timeLeft > 0) return;
    checkArrangement(true);
  }, [checkArrangement, finished, roundStarted, timeLeft, timerRunning]);

  const startRound = () => {
    if (!currentRound || finished || roundSolved) return;
    setFeedback(null);
    setIncorrectSlots([]);
    setTimeLeft(currentRound.timeLimitSeconds);
    setRoundStarted(true);
    setTimerRunning(true);
    logGameTelemetry(MODE_ID, "question_started", {
      roundIndex: roundIndex + 1,
      title: currentRound.title,
      durationSeconds: currentRound.timeLimitSeconds,
      frameCount: currentRound.frames.length,
      replay: Boolean(feedback),
    });
  };

  const toggleTimerRunning = () => {
    if (!roundStarted || roundSolved || finished) return;
    setTimerRunning((prev) => !prev);
  };

  const handleExit = async () => {
    logGameTelemetry(MODE_ID, "session_end", {
      solved: finished,
      score,
      correctCount,
      roundIndex,
      totalRounds,
      durationMs: Date.now() - startedAtRef.current,
    });
    if (!finished && score > 0 && !xpSaved) await saveXp(score);
    navigate("/modes");
  };

  const restartMode = () => {
    logGameTelemetry(MODE_ID, "session_end", {
      solved: false,
      score,
      correctCount,
      roundIndex,
      totalRounds,
      reason: "restart",
      durationMs: Date.now() - startedAtRef.current,
    });
    resetSession(true);
  };

  const moveNextRound = () => {
    if (!roundSolved || finished) return;
    prepareRound(roundIndex + 1);
  };

  const clearArrangement = () => {
    if (!timerRunning || roundSolved || finished) return;
    setSelectedFrameIds([]);
    setFeedback(null);
    setIncorrectSlots([]);
  };

  const placeFrame = (frameId) => {
    if (!timerRunning || roundSolved || finished || !currentRound) return;
    setSelectedFrameIds((prev) => {
      if (prev.includes(frameId) || prev.length >= currentRound.frames.length) return prev;
      return [...prev, frameId];
    });
  };

  const removeFrameAt = (index) => {
    if (!timerRunning || roundSolved || finished) return;
    setSelectedFrameIds((prev) => prev.filter((_, currentIndex) => currentIndex !== index));
  };

  const moveFrame = (index, direction) => {
    if (!timerRunning || roundSolved || finished) return;
    setSelectedFrameIds((prev) => {
      const nextIndex = index + direction;
      if (nextIndex < 0 || nextIndex >= prev.length) return prev;
      const next = [...prev];
      [next[index], next[nextIndex]] = [next[nextIndex], next[index]];
      return next;
    });
  };

  useKeyboardShortcuts(
    {
      Escape: handleExit,
      Enter: () => roundStarted && timerRunning && !roundSolved && checkArrangement(false),
      " ": () => {
        if (!roundStarted && !finished) return startRound();
        if (roundStarted && !roundSolved && !finished) toggleTimerRunning();
      },
    },
    !finished
  );

  if (loading || (totalRounds > 0 && !sessionReady)) {
    return <div className="theme-page game-screen h-screen flex items-center justify-center bg-slate-950 text-amber-300">Đang chuẩn bị phần xâu chuỗi diễn biến...</div>;
  }
  if (!currentRound || totalRounds === 0) {
    return <div className="theme-page game-screen h-screen flex items-center justify-center bg-slate-950 text-amber-300">Chưa có bộ dữ liệu hợp lệ cho chế độ chơi này.</div>;
  }

  return (
    <div className="theme-page game-screen h-screen flex flex-col overflow-hidden bg-[radial-gradient(circle_at_top,#7c2d12_0%,#020617_72%)] px-4 py-4 text-white sm:px-6">
      <div className="mx-auto flex h-full w-full max-w-7xl flex-1 flex-col gap-4 min-h-0">
        <div className="grid gap-3 rounded-[28px] border border-white/10 bg-slate-900/80 p-3 shadow-2xl md:grid-cols-[1fr_auto_1fr] md:items-center sm:p-4">
          <div className="flex justify-center md:justify-start">
            <button onClick={handleExit} className="inline-flex items-center gap-2 rounded-full border border-white/10 px-4 py-2 text-sm font-bold text-slate-200 transition hover:bg-white/5"><ArrowLeft size={18} />Thoát Với {score} XP</button>
          </div>
          <div className="text-center">
            <div className="inline-flex items-center gap-2 rounded-full bg-amber-500/10 px-4 py-2 text-xs font-black uppercase tracking-[0.24em] text-amber-200"><ListOrdered size={16} />Xâu Chuỗi Diễn Biến</div>
            <h1 className="vn-safe-heading mt-3 text-2xl font-black tracking-[0.08em] text-white sm:text-3xl">Lượt {roundIndex + 1}/{totalRounds}</h1>
            <p className="mt-2 text-sm text-slate-300">{currentRound.title}</p>
          </div>
          <div className="flex items-center justify-center gap-3 md:justify-end">
            <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-3 text-center"><div className="text-[11px] uppercase tracking-[0.2em] text-slate-400">Hoàn Thành</div><div className="text-lg font-black text-white">{correctCount}/{totalRounds}</div></div>
            <div className="rounded-2xl border border-amber-400/20 bg-amber-500/10 px-4 py-3 text-center"><div className="text-[11px] uppercase tracking-[0.2em] text-amber-200/80">Điểm</div><div className="text-lg font-black text-amber-200">{score}</div></div>
          </div>
        </div>

        <div className="grid flex-1 min-h-0 items-stretch gap-4 xl:grid-cols-[minmax(340px,0.94fr)_minmax(0,1.06fr)]">
          <div className="rounded-[28px] border border-white/10 bg-slate-900/80 p-4 shadow-xl sm:p-5">
            <div className="flex items-start justify-between gap-4">
              <div>
                <div className="text-xs font-black uppercase tracking-[0.24em] text-slate-400">Video Tư Liệu</div>
                <h2 className="mt-2 text-2xl font-black text-white">{currentRound.title}</h2>
                <p className="mt-3 text-sm leading-6 text-slate-300">{currentRound.instruction}</p>
              </div>
              <a href={currentRound.videoUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-full border border-white/10 px-4 py-2 text-xs font-black uppercase tracking-[0.14em] text-slate-200 transition hover:bg-white/5"><ExternalLink size={14} />Mở Video</a>
            </div>
            <div className="mt-4 overflow-hidden rounded-[24px] border border-white/10 bg-slate-950/60">
              {currentRound.embedUrl ? (
                <div className="aspect-video w-full"><iframe src={currentRound.embedUrl} title={currentRound.title} className="h-full w-full" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen /></div>
              ) : (
                <div className="flex aspect-video items-center justify-center px-6 text-center text-sm text-slate-400">Không nhúng được video. Hãy dùng nút Mở Video để xem bản gốc.</div>
              )}
            </div>
            <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
              <div className="rounded-2xl border border-amber-400/20 bg-amber-500/10 px-4 py-4 text-center"><div className="text-[11px] uppercase tracking-[0.2em] text-amber-200/80 font-black">Đồng Hồ</div><div className="mt-2 flex items-center justify-center gap-2 text-2xl font-black text-amber-200"><Clock3 size={20} />{roundStarted ? `${timeLeft}s` : `${currentRound.timeLimitSeconds}s`}</div></div>
              <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-4 text-center"><div className="text-[11px] uppercase tracking-[0.2em] text-slate-400">Khung Hình</div><div className="mt-2 text-2xl font-black text-white">{selectedFrameIds.length}/{currentRound.frames.length}</div></div>
              <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-4 text-center"><div className="text-[11px] uppercase tracking-[0.2em] text-slate-400">Thưởng</div><div className="mt-2 text-2xl font-black text-emerald-300">{currentRound.xpReward} XP</div></div>
              <button onClick={restartMode} className="rounded-2xl border border-white/10 bg-slate-800 px-5 py-4 font-black uppercase tracking-[0.16em] text-white transition hover:bg-slate-700"><span className="inline-flex items-center gap-2"><RotateCcw size={16} />Chơi Lại</span></button>
            </div>
            <div className="mt-4 grid gap-3 sm:grid-cols-2">
              <button onClick={startRound} disabled={timerRunning || finished || roundSolved} className="rounded-2xl bg-amber-400 px-5 py-4 font-black uppercase tracking-[0.18em] text-slate-950 transition hover:bg-amber-300 disabled:opacity-50"><span className="inline-flex items-center gap-2"><PlayCircle size={18} />{feedback && !roundSolved ? "Bắt Đầu Lại" : "Bắt Đầu Sắp Xếp"}</span></button>
              <button onClick={toggleTimerRunning} disabled={!roundStarted || roundSolved || finished} className="rounded-2xl border border-white/10 bg-slate-800 px-5 py-4 font-black uppercase tracking-[0.18em] text-white transition hover:bg-slate-700 disabled:opacity-50"><span className="inline-flex items-center gap-2"><PauseCircle size={18} />{roundStarted && !timerRunning ? "Tiếp Tục" : "Dừng"}</span></button>
              <button onClick={() => checkArrangement(false)} disabled={!roundStarted || !timerRunning || roundSolved} className="rounded-2xl bg-emerald-500 px-5 py-4 font-black uppercase tracking-[0.18em] text-slate-950 transition hover:bg-emerald-400 disabled:opacity-50"><span className="inline-flex items-center gap-2"><CheckCircle2 size={18} />Kiểm Tra Thứ Tự</span></button>
              <button onClick={clearArrangement} disabled={!timerRunning || roundSolved || finished} className="rounded-2xl border border-white/10 bg-slate-800 px-5 py-4 font-black uppercase tracking-[0.18em] text-white transition hover:bg-slate-700 disabled:opacity-50">Xóa Thứ Tự</button>
            </div>
            <div className={`mt-4 rounded-2xl border px-5 py-4 ${feedback ? (feedback.type === "success" ? "border-emerald-400/30 bg-emerald-500/10" : feedback.type === "warning" ? "border-amber-400/30 bg-amber-500/10" : "border-rose-400/30 bg-rose-500/10") : "border-dashed border-white/10 bg-slate-950/40"}`}>
              <div className="text-sm font-semibold text-white">{feedback?.text || "Xem video trước, rồi bấm Bắt Đầu Sắp Xếp để mở lượt chơi và xếp các khung hình từ sớm đến muộn."}</div>
            </div>
            {roundSolved && !finished ? <button onClick={moveNextRound} className="mt-4 w-full rounded-2xl bg-sky-400 px-5 py-4 text-base font-black uppercase tracking-[0.18em] text-slate-950 transition hover:bg-sky-300">Sang Video Tiếp Theo</button> : null}
          </div>

          <div className="flex min-h-0 flex-col rounded-[28px] border border-white/10 bg-slate-900/80 p-4 shadow-xl sm:p-5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <div className="text-xs font-black uppercase tracking-[0.24em] text-slate-400">Bảng Sắp Xếp</div>
                <div className="mt-2 text-sm text-slate-300">Nhấn vào khung hình bên dưới để đưa vào timeline. Khi đã đặt vào thứ tự, bạn có thể dịch trái, dịch phải hoặc bỏ ra.</div>
              </div>
              <div className="inline-flex items-center gap-2 rounded-full bg-amber-500/10 px-4 py-2 text-xs font-black uppercase tracking-[0.16em] text-amber-200"><Film size={14} />{currentRound.frames.length} Khung</div>
            </div>
            <div className="mt-4 custom-scrollbar flex-1 overflow-y-auto pr-1">
              <div className="space-y-3">
                {currentRound.frames.map((_, index) => {
                  const frame = selectedFrames[index];
                  const slotClass = roundSolved ? "border-emerald-400/30 bg-emerald-500/10" : incorrectSlots.includes(index) ? "border-rose-400/30 bg-rose-500/10" : "border-white/10 bg-slate-950/60";
                  return (
                    <div key={`${currentRound.id}-slot-${index + 1}`} className={`rounded-[24px] border p-4 ${slotClass}`}>
                      <div className="flex items-start gap-4">
                        <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-2xl bg-amber-500/15 text-base font-black text-amber-200">{index + 1}</div>
                        {frame ? (
                          <div className="min-w-0 flex-1">
                            <div className="overflow-hidden rounded-2xl border border-white/10 bg-slate-900"><img src={frame.imageUrl} alt={`${currentRound.title} - bước ${index + 1}`} className="h-40 w-full object-cover sm:h-48" /></div>
                            {frame.caption ? <div className="mt-3 text-sm text-slate-300">{frame.caption}</div> : null}
                            <div className="mt-3 flex flex-wrap gap-2">
                              <button onClick={() => moveFrame(index, -1)} disabled={!timerRunning || index === 0 || roundSolved || finished} className="rounded-full border border-white/10 px-3 py-2 text-xs font-black uppercase tracking-[0.14em] text-slate-200 transition hover:bg-white/5 disabled:opacity-40">Sang Trái</button>
                              <button onClick={() => moveFrame(index, 1)} disabled={!timerRunning || index === selectedFrames.length - 1 || roundSolved || finished} className="rounded-full border border-white/10 px-3 py-2 text-xs font-black uppercase tracking-[0.14em] text-slate-200 transition hover:bg-white/5 disabled:opacity-40">Sang Phải</button>
                              <button onClick={() => removeFrameAt(index)} disabled={!timerRunning || roundSolved || finished} className="rounded-full border border-rose-400/20 px-3 py-2 text-xs font-black uppercase tracking-[0.14em] text-rose-200 transition hover:bg-rose-500/10 disabled:opacity-40">Bỏ Ra</button>
                            </div>
                          </div>
                        ) : (
                          <div className="flex min-h-40 flex-1 items-center justify-center rounded-2xl border border-dashed border-white/10 bg-slate-900/50 px-4 py-6 text-center text-sm text-slate-500">Chưa có khung hình ở vị trí này.</div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="mt-4 rounded-[24px] border border-white/10 bg-slate-950/50 p-4">
                <div className="flex items-center justify-between gap-3">
                  <div className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Kho Khung Hình</div>
                  <div className="text-xs font-black uppercase tracking-[0.16em] text-slate-500">{availableFrames.length} còn lại</div>
                </div>
                <div className="mt-4">
                  {availableFrames.length > 0 ? (
                    <div className="grid gap-3 sm:grid-cols-2">
                      {availableFrames.map((frame) => (
                        <button key={frame.id} type="button" onClick={() => placeFrame(frame.id)} disabled={!timerRunning || roundSolved || finished} className="overflow-hidden rounded-[22px] border border-white/10 bg-slate-900/80 text-left transition hover:border-amber-300/40 hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50">
                          <img src={frame.imageUrl} alt={currentRound.title} className="h-40 w-full object-cover" />
                          <div className="px-4 py-3 text-xs font-black uppercase tracking-[0.16em] text-slate-300">Chọn vào thứ tự</div>
                        </button>
                      ))}
                    </div>
                  ) : (
                    <div className="rounded-2xl border border-dashed border-white/10 px-4 py-6 text-center text-sm text-slate-500">Tất cả khung hình đã được đưa vào timeline. Kiểm tra lại thứ tự rồi nộp kết quả.</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {finished ? (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 px-4 backdrop-blur-sm">
            <Confetti active={true} count={100} />
            <div className="w-full max-w-3xl rounded-[32px] border border-emerald-400/20 bg-slate-900/95 p-6 text-center shadow-2xl sm:p-8">
              <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300"><Trophy size={40} /></div>
              <h2 className="vn-safe-heading mt-5 text-3xl font-black tracking-[0.08em] text-emerald-300 sm:text-4xl">Hoàn thành Xâu chuỗi diễn biến</h2>
              <p className="mt-4 text-slate-300">Bạn đã sắp xếp đúng toàn bộ {totalRounds} video và khôi phục chính xác mạch diễn biến của từng sự kiện.</p>
              <div className="mt-8 grid gap-4 sm:grid-cols-3">
                <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-5"><div className="text-xs font-black uppercase tracking-[0.22em] text-slate-400">Đúng</div><div className="mt-2 text-3xl font-black text-white">{correctCount}/{totalRounds}</div></div>
                <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-5"><div className="text-xs font-black uppercase tracking-[0.22em] text-slate-400">Video</div><div className="mt-2 text-3xl font-black text-white">{totalRounds}</div></div>
                <div className="rounded-2xl border border-white/10 bg-slate-800/80 px-4 py-5"><div className="text-xs font-black uppercase tracking-[0.22em] text-slate-400">Điểm</div><div className="mt-2 text-3xl font-black text-amber-300">{score}</div></div>
              </div>
              <div className="mt-8 flex flex-col gap-3 sm:flex-row">
                <button onClick={restartMode} className="flex-1 rounded-2xl bg-amber-400 px-5 py-4 font-black text-slate-950 transition hover:bg-amber-300">Chơi Lại</button>
                <button onClick={() => navigate("/modes")} className="flex-1 rounded-2xl border border-white/10 bg-slate-800 px-5 py-4 font-black text-white transition hover:bg-slate-700">Về Chủ Đề 4</button>
              </div>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}
